CREATE TABLE "voucher_payment" ( "payment_id" integer NOT NULL, "code" text NOT NULL, "kind" public.payment_kind GENERATED ALWAYS AS ('voucher') STORED, PRIMARY KEY ("payment_id"), CONSTRAINT "fk-voucher_payment-payment_id-kind" FOREIGN KEY ("payment_id", "kind") REFERENCES "payment" ("id", "kind") ON DELETE CASCADE DEFERRABLE INITIALLY IMMEDIATE );
ALTER TABLE "payment" ADD COLUMN "voucher_id" integer GENERATED ALWAYS AS ((CASE WHEN ("kind" = 'voucher') THEN "id" END)) STORED, ADD CONSTRAINT "fk-payment-voucher_id" FOREIGN KEY ("voucher_id") REFERENCES "voucher_payment" ("payment_id") DEFERRABLE INITIALLY IMMEDIATE;
